package android.content; public class Context { public final android.app.NotificationManager notifications=new android.app.NotificationManager();public final android.app.AlarmManager alarms=new android.app.AlarmManager();public final SharedPreferences prefs=new SharedPreferences();public <T>T getSystemService(Class<T> k){return k.cast(k==android.app.NotificationManager.class?notifications:alarms);} }